      <div class="path"><div class="ph"><span class="k">${esc(T('path'))}</span><b>${esc(EQ_LEVEL_NAME[lv][L])}</b><i>${esc(code)}</i></div><p class="pk">${esc(T('first'))}</p>
        <ul>${EQ_PATH[lv].map(([ic, t], i) => `<li style="--i:${i}">${jv(ic, 34)}<span>${esc(t[L])}</span></li>`).join('')}</ul></div>
