    const api = { lang: opts.lang, age: opts.age, soundOn: () => true, sound(n) { const m = { pop: 'pop', click: 'click', ok: 'chime', bad: 'unselect', finish: 'fanfare' }; try { window.JuniorSfx && window.JuniorSfx(m[n] || 'click'); } catch (e) {} }, startCommit: async () => true, commitAnswer: async () => true, onState() {}, onComplete: opts.onComplete, onExit: opts.onExit };
